// The Braided Divide. All authoring is Source-local METRES. Runtime cells are
// converted at the boundary, never mixed into this construction manifest.
// Ground, raised solid work, actual model tops and the passages below them are
// separate surfaces. Merely standing under a crossing cannot acquire its floor.
import { SOURCE_HANGING_SHORE } from './source-hanging-shore.js';

const freeze = Object.freeze;
const clamp = (n, a, b) => Math.max(a, Math.min(b, n));
const EPS = 1e-6;
export const SOURCE_BRAIDED_DIVIDE = freeze({
  version: 1, minX: -90, maxX: 90, frontZ: SOURCE_HANGING_SHORE.bank.frontZ,
  backZ: -540, length: 150, lower: 4.2, middle: 9, upper: 15.2,
  underside: SOURCE_HANGING_SHORE.bank.underside,
  finalRise: freeze({ from: 118, to: 146 }),
  court: freeze({ x: -12, z: -465, floor: 4.2, minX: -12, maxX: 12, from: 67, to: 84 }),
  crossings: freeze([freeze({ id: 'case-crossing', depth: 50, floor: 9 }), freeze({ id: 'piano-crossing', depth: 107, floor: 15.2 })]),
});
const S = SOURCE_BRAIDED_DIVIDE;
export const sourceDivideDepth = z => S.frontZ - Number(z);
export const sourceDivideZ = depth => S.frontZ - Number(depth);
export function sourceDivideContains(x, z, margin = 0) {
  const d = sourceDivideDepth(z);
  return Number.isFinite(x) && Number.isFinite(z) && x >= S.minX + margin && x <= S.maxX - margin && d >= 0 && d <= S.length;
}
export function sourceDivideFloorAt(x, z) {
  if (!sourceDivideContains(x, z)) return null;
  const d = sourceDivideDepth(z);
  return S.lower + (S.upper - S.lower) * clamp((d - S.finalRise.from) / (S.finalRise.to - S.finalRise.from), 0, 1);
}

const rectangle = (minX, maxX, from, to) => [[minX, sourceDivideZ(from)], [maxX, sourceDivideZ(from)], [maxX, sourceDivideZ(to)], [minX, sourceDivideZ(to)]];
const colour = freeze({ bank: [.24, .27, .25], ramp: [.31, .34, .30], crossing: [.27, .29, .25], court: [.32, .33, .29], ground: [.19, .22, .20], support: [.23, .25, .23] });
const solids = [];
function solid(id, polygon, bottom, top, kind = 'bank', extra = {}) {
  const result = { id, polygon, bottom, top, kind, color: colour[kind] || colour.bank, ...extra };
  solids.push(result); return result;
}
const box = (id, minX, maxX, from, to, top, kind = 'bank', bottom = S.lower) => solid(id, rectangle(minX, maxX, from, to), bottom, () => top, kind);
const ramp = (id, minX, maxX, from, to, low, high) => solid(id, rectangle(minX, maxX, from, to), S.lower, (_x, z) => low + (high - low) * clamp((sourceDivideDepth(z) - from) / (to - from), 0, 1), 'ramp', { from, to, low, high });

box('west-middle-bank', -88, -26, 42, 82, S.middle);
box('east-middle-bank', 24, 88, 47, 98, S.middle);
box('west-middle-projection', -26, -18, 58, 65, S.middle);
box('east-middle-projection', 12, 24, 86, 93, S.middle);
box('west-upper-bank', -88, -32, 106, 150, S.upper);
box('east-upper-bank', 20, 88, 108, 150, S.upper);
ramp('west-front-ramp', -42, -24, 22, 42, S.lower, S.middle);
